/* HEXA BATTLEGROUNDS setup — PART 57 OF 57. Run parts in order. Safe to re-run. */ create function _tick(p_arena uuid, p_force boolean default false) returns boolean language plpgsql as $$ declare v boolean; begin v := _tick_core(p_arena, p_force); if exists (select 1 from bots where arena_id = p_arena) then if _bots_step(p_arena) then v := true; end if; end if; return v; end $$; create or replace function arena_positions(p_token text) returns jsonb language plpgsql security definer set search_path = public as $$ declare p players; t teams; v_scan boolean; begin p := _auth_player(p_token); select * into t from teams where id = p.team_id; if exists (select 1 from bots where arena_id = t.arena_id) then perform _tick(t.arena_id); end if; v_scan := t.scan_until is not null and t.scan_until > now(); return jsonb_build_object('server_now', now(), 'squads', (select coalesce(jsonb_agg(jsonb_build_object( 'id', tm.id, 'level', tm.level, 'bldg', tm.bldg, 'state', tm.state, 'pos', to_jsonb(_team_xy(tm)), 'age', case when tm.state = 'idle' and tm.pos_at is not null then round(extract(epoch from now() - tm.pos_at)::numeric, 2) end, 'vel', case when tm.state = 'traveling' and tm.travel_arrive_at > now() and l.id is not null then jsonb_build_array((l.x - coalesce(tm.travel_fx, l.x)) / greatest(0.2, extract(epoch from tm.travel_arrive_at - tm.travel_started_at)), (l.y - coalesce(tm.travel_fy, l.y)) / greatest(0.2, extract(epoch from tm.travel_arrive_at - tm.travel_started_at))) when tm.state = 'idle' and tm.pos_at > now() - interval '3 seconds' and (tm.vel_x <> 0 or tm.vel_y <> 0) then jsonb_build_array(tm.vel_x, tm.vel_y) end)), '[]'::jsonb) from teams tm left join locations l on l.id = tm.travel_to where tm.arena_id = t.arena_id and tm.ready and (tm.id = t.id or v_scan or tm.location_id = t.location_id or tm.jammed_until is null or tm.jammed_until < now() or exists (select 1 from alliances al where al.status = 'active' and ((al.team_a = t.id and al.team_b = tm.id) or (al.team_b = t.id and al.team_a = tm.id)))))); end $$; do $$ declare f record; begin for f in select p.oid::regprocedure as sig, p.proname from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname = 'public' and p.prokind = 'f' loop execute format('revoke all on function %s from public', f.sig); begin execute format('revoke all on function %s from anon, authenticated', f.sig); exception when undefined_object then null; end; if f.proname = any(array['map_data', 'join_team', 'claim_role', 'player_state', 'captain_move', 'captain_explore', 'captain_submit', 'captain_hint', 'captain_use_item', 'captain_buy', 'captain_attack', 'captain_claim_airdrop', 'captain_chat', 'captain_block', 'captain_report', 'captain_alliance', 'captain_bargain', 'host_create_event', 'host_login', 'host_generate_teams', 'host_import_teams', 'host_overview', 'host_command', 'host_settings', 'host_missions', 'host_save_mission', 'host_test_answer', 'host_chat_log', 'host_audit', 'host_export', 'spectator_state', 'host_roster', 'captain_steer', 'captain_reveal', 'captain_stairs', 'arena_positions', 'host_fixed_cards', 'card_event', 'demo_create', 'host_extras', 'demo_view', 'demo_status', 'demo_control', 'demo_pulse', 'demo_end']) then begin execute format('grant execute on function %s to anon, authenticated', f.sig); exception when undefined_object then null; end; end if; end loop; end $$;
